#include "ipc.h"
#include <assert.h>
#include <pthread.h>
#include <sched.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>

static atomic_flag gate=ATOMIC_FLAG_INIT;
static atomic_uint raced_sent, raced_received;
static atomic_uint move_ready, move_go;
static atomic_int move_result[2];
static uint64_t raced_move_handle;
static _Thread_local unsigned gate_depth;
static uintptr_t lock_table(void *p){(void)p;if(gate_depth++)return 0;while(atomic_flag_test_and_set_explicit(&gate,memory_order_acquire)){}return 0;}
static void unlock_table(void *p,uintptr_t f){(void)p;(void)f;assert(gate_depth);if(--gate_depth==0)atomic_flag_clear_explicit(&gate,memory_order_release);}
static void *allocate(void *p,size_t n){(void)p;return calloc(1,n);}
static void release(void *p,void *v){(void)p;free(v);}
static void object_destroy(lamix_object *o){free(o->context);free(o);}
static lamix_handle_table table;
static uint64_t anchor,send_endpoint,receive_endpoint;
static void *worker(void *unused){(void)unused;for(unsigned i=0;i<5000;i++){uint64_t duplicate=0;assert(lamix_handle_duplicate(&table,anchor,LAMIX_RIGHT_SHM_READ,&duplicate)==LH_OK);lamix_object *found=0;assert(lamix_handle_lookup(&table,duplicate,LAMIX_OBJECT_SHM,LAMIX_RIGHT_SHM_READ,&found)==LH_OK);lamix_object_release(found);assert(lamix_handle_close(&table,duplicate)==LH_OK);lamix_object *o=calloc(1,sizeof(*o));assert(o);o->context=calloc(1,1);assert(o->context);lamix_object_init(o,LAMIX_OBJECT_SHM,o->context,object_destroy);uint64_t h=0;assert(lamix_handle_install(&table,o,LAMIX_RIGHT_SHM_READ,&h)==LH_OK);lamix_object_release(o);assert(lamix_handle_lookup(&table,h,LAMIX_OBJECT_SHM,LAMIX_RIGHT_SHM_READ,&found)==LH_OK);lamix_object_release(found);assert(lamix_handle_close(&table,h)==LH_OK);}return 0;}
static void *ipc_alloc(void *p,size_t n){(void)p;return calloc(1,n);}
static void ipc_free(void *p,void *v){(void)p;free(v);}
static uintptr_t ipc_lock(void *p){return lock_table(p);}
static void ipc_unlock(void *p,uintptr_t f){unlock_table(p,f);}
#define IPC_MESSAGES 3000u
static void *producer(void *unused){(void)unused;for(uint64_t value=0;value<IPC_MESSAGES;value++){lamix_ipc_status s;do{s=lamix_channel_send(&table,&(lamix_ipc_ops){0,ipc_alloc,ipc_free,ipc_lock,ipc_unlock},send_endpoint,&value,sizeof(value),0,0);if(s==LI_AGAIN)sched_yield();}while(s==LI_AGAIN);assert(s==LI_OK);}return 0;}
static void *consumer(void *unused){(void)unused;lamix_ipc_ops ops={0,ipc_alloc,ipc_free,ipc_lock,ipc_unlock};for(uint64_t expected=0;expected<IPC_MESSAGES;){uint64_t value=UINT64_MAX;size_t length=0,count=0;lamix_ipc_status s=lamix_channel_receive(&table,&ops,receive_endpoint,&value,sizeof(value),&length,0,0,&count);if(s==LI_AGAIN){sched_yield();continue;}assert(s==LI_OK&&length==sizeof(value)&&count==0&&value==expected);++expected;}return 0;}
static void *race_producer(void *unused){(void)unused;lamix_ipc_ops ops={0,ipc_alloc,ipc_free,ipc_lock,ipc_unlock};for(uint64_t value=0;;++value){lamix_ipc_status s;do{s=lamix_channel_send(&table,&ops,send_endpoint,&value,sizeof(value),0,0);if(s==LI_AGAIN)sched_yield();}while(s==LI_AGAIN);if(s==LI_BADF||s==LI_CLOSED)break;assert(s==LI_OK);atomic_fetch_add_explicit(&raced_sent,1,memory_order_release);}return 0;}
static void *race_consumer(void *unused){(void)unused;lamix_ipc_ops ops={0,ipc_alloc,ipc_free,ipc_lock,ipc_unlock};uint64_t expected=0;for(;;){uint64_t value=UINT64_MAX;size_t length=0,count=0;lamix_ipc_status s=lamix_channel_receive(&table,&ops,receive_endpoint,&value,sizeof(value),&length,0,0,&count);if(s==LI_AGAIN){sched_yield();continue;}if(s==LI_CLOSED)break;assert(s==LI_OK&&length==sizeof(value)&&count==0&&value==expected++);atomic_fetch_add_explicit(&raced_received,1,memory_order_release);}return 0;}
static void *move_sender(void *opaque){unsigned id=(unsigned)(uintptr_t)opaque;lamix_ipc_ops ops={0,ipc_alloc,ipc_free,ipc_lock,ipc_unlock};lamix_attachment a={.handle=raced_move_handle,.rights=LAMIX_RIGHT_SHM_READ,.disposition=LAMIX_ATTACHMENT_MOVE};atomic_fetch_add_explicit(&move_ready,1,memory_order_release);while(!atomic_load_explicit(&move_go,memory_order_acquire))sched_yield();uint64_t value=id;move_result[id]=lamix_channel_send(&table,&ops,send_endpoint,&value,sizeof(value),&a,1);return 0;}
static void *race_closer(void *unused){(void)unused;while(atomic_load_explicit(&raced_sent,memory_order_acquire)<500)sched_yield();assert(lamix_handle_close(&table,send_endpoint)==LH_OK);return 0;}
int main(void){assert(lamix_handle_table_init(&table,0,allocate,release,lock_table,unlock_table)==LH_OK);lamix_object *base=calloc(1,sizeof(*base));base->context=calloc(1,1);lamix_object_init(base,LAMIX_OBJECT_SHM,base->context,object_destroy);assert(lamix_handle_install(&table,base,LAMIX_RIGHT_SHM_READ,&anchor)==LH_OK);lamix_object_release(base);lamix_ipc_ops ops={0,ipc_alloc,ipc_free,ipc_lock,ipc_unlock};assert(lamix_channel_create(&table,&ops,&send_endpoint,&receive_endpoint)==LI_OK);pthread_t workers[4],send,receive;for(unsigned i=0;i<4;i++)assert(pthread_create(&workers[i],0,worker,0)==0);assert(pthread_create(&send,0,producer,0)==0);assert(pthread_create(&receive,0,consumer,0)==0);for(unsigned i=0;i<4;i++)assert(pthread_join(workers[i],0)==0);assert(pthread_join(send,0)==0);assert(pthread_join(receive,0)==0);lamix_object *cap=calloc(1,sizeof(*cap));cap->context=calloc(1,1);lamix_object_init(cap,LAMIX_OBJECT_SHM,cap->context,object_destroy);uint64_t cap_handle=0;assert(lamix_handle_install(&table,cap,LAMIX_RIGHT_TRANSFER|LAMIX_RIGHT_SHM_READ,&cap_handle)==LH_OK);lamix_object_release(cap);lamix_attachment attachment={.handle=cap_handle,.rights=LAMIX_RIGHT_SHM_READ,.disposition=LAMIX_ATTACHMENT_DUP};uint64_t value=9;assert(lamix_channel_send(&table,&ops,send_endpoint,&value,sizeof(value),&attachment,1)==LI_OK);lamix_attachment received_cap[1];size_t length=0,count=0;assert(lamix_channel_receive(&table,&ops,receive_endpoint,&value,sizeof(value),&length,received_cap,1,&count)==LI_OK&&count==1);assert(lamix_handle_close(&table,cap_handle)==LH_OK);assert(lamix_handle_close(&table,received_cap[0].handle)==LH_OK);assert(lamix_handle_close(&table,anchor)==LH_OK);assert(lamix_channel_create(&table,&ops,&send_endpoint,&receive_endpoint)==LI_OK);pthread_t race_send,race_recv,closer;assert(pthread_create(&race_send,0,race_producer,0)==0);assert(pthread_create(&race_recv,0,race_consumer,0)==0);assert(pthread_create(&closer,0,race_closer,0)==0);assert(pthread_join(closer,0)==0);assert(pthread_join(race_send,0)==0);assert(pthread_join(race_recv,0)==0);assert(atomic_load(&raced_sent)==atomic_load(&raced_received));assert(lamix_handle_close(&table,receive_endpoint)==LH_OK);assert(lamix_channel_create(&table,&ops,&send_endpoint,&receive_endpoint)==LI_OK);lamix_object *moving=calloc(1,sizeof(*moving));moving->context=calloc(1,1);lamix_object_init(moving,LAMIX_OBJECT_SHM,moving->context,object_destroy);assert(lamix_handle_install(&table,moving,LAMIX_RIGHT_TRANSFER|LAMIX_RIGHT_SHM_READ,&raced_move_handle)==LH_OK);lamix_object_release(moving);pthread_t movers[2];for(uintptr_t i=0;i<2;i++)assert(pthread_create(&movers[i],0,move_sender,(void *)i)==0);while(atomic_load_explicit(&move_ready,memory_order_acquire)<2)sched_yield();atomic_store_explicit(&move_go,1,memory_order_release);for(unsigned i=0;i<2;i++)assert(pthread_join(movers[i],0)==0);assert((move_result[0]==LI_OK&&move_result[1]==LI_BADF)||(move_result[1]==LI_OK&&move_result[0]==LI_BADF));assert(lamix_handle_lookup(&table,raced_move_handle,0,0,0)==LH_BADF);uint64_t received_value=0;lamix_attachment moved[1];size_t moved_count=0;assert(lamix_channel_receive(&table,&ops,receive_endpoint,&received_value,sizeof(received_value),&length,moved,1,&moved_count)==LI_OK&&moved_count==1);assert(lamix_handle_close(&table,moved[0].handle)==LH_OK);assert(lamix_handle_close(&table,send_endpoint)==LH_OK);assert(lamix_handle_close(&table,receive_endpoint)==LH_OK);lamix_handle_table_destroy(&table);return 0;}
